values
('TRGG-GUEST-0728', 'Nakano, Soichiro', 'en', 'caddy_booking', 'Why is booking at Burapha so slow?', 'Every TRGG day at Burapha it''s the same: call, wait, call back, wait. 6 Oct took three days to confirm one caddy. Please get Burapha onto the app.', 'Travellers Rest Golf Group', 'open', 'low', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-04 11:53:10+07', '2026-10-04 11:53:10+07'),
('TRGG-GUEST-0364', 'Hansen, Allan', 'en', 'caddy_booking', 'Burapha says no caddies - again', 'Second time at Burapha I''ve been told ''no caddy'' for a TRGG day. 6 Oct is the Tuesday and they''re ''full''. Do they actually have caddies on the roster any more?', 'Travellers Rest Golf Group', 'open', 'high', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-04 11:40:47+07', '2026-10-04 11:40:47+07'),
('TRGG-GUEST-1024', 'Vaghela, Suresh', 'en', 'caddy_booking', 'Burapha took 3 days to confirm a caddy', 'Asked Burapha for a caddy for 6 Oct and it took 3 days and four messages to get a yes. By then half the group had given up and booked elsewhere.', 'Travellers Rest Golf Group', 'open', 'high', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-04 10:10:52+07', '2026-10-04 10:10:52+07'),
('KAKAO-4911042963', '파타야 조아골프(강동주)', 'ko', 'caddy_booking', '부라파 예약이 너무 오래 걸려요', '10월 6일 라운드 캐디 예약 확인 받는 데 3일 걸렸어요. 앱으로 바로 예약되면 좋겠습니다.', 'Travellers Rest Golf Group', 'resolved', 'normal', NULL, '2026-10-04 17:31:11+07', 'U2b6d976f19bca4b2f4374ae0e10ed873', 'seed_wave4_20261004', '2026-10-04 08:29:26+07', '2026-10-04 17:31:11+07'),
('U657c6033b696a24ed75b16158ea4f535', '김경태 (Kyungtae Kim)', 'ko', 'caddy_booking', '부라파 캐디가 없대요', '10월 6일 부라파 9:35 티오프인데 캐디 예약하려니 캐디가 없다고 합니다. 이렇게 큰 골프장에서 어떻게 캐디가 없나요?', 'Travellers Rest Golf Group', 'in_progress', 'normal', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-03 20:23:03+07', '2026-10-04 08:08:24+07'),
('TRGG-GUEST-0965', 'Suh, Minkyo', 'en', 'caddy_booking', 'Still waiting on Burapha', 'Sent my caddy request to Burapha on Friday for the 6 Oct round. Still no reply. Booking a caddy shouldn''t take longer than booking the flight here.', 'Travellers Rest Golf Group', 'open', 'normal', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-03 18:34:21+07', '2026-10-03 18:34:21+07'),
('KAKAO-4911042963', '파타야 조아골프(강동주)', 'ko', 'caddy_booking', '이스턴스타 영어가 안 통해요', '이스턴스타에 캐디 예약하려고 3번 전화했는데 영어를 하는 직원이 없어요. 10월 8일 라운드 캐디 예약 부탁드립니다.', 'Travellers Rest Golf Group', 'in_progress', 'high', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-03 09:10:33+07', '2026-10-04 01:00:36+07'),
('Ubf3b7121aee6641bfd82e03566de1550', 'Folan, Mick', 'en', 'other', 'Not playing Pattaya CC until the greens are fixed', 'That''s me done with Pattaya CC until the greens come back. 28 Sep was the last straw — the back nine was unplayable. I''ll skip the TRGG Mondays there and play elsewhere.', 'Travellers Rest Golf Group', 'open', 'high', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-02 20:01:12+07', '2026-10-02 20:01:12+07'),
('MANUAL-1788838471801-bdt4l6w', 'John Cooke', 'en', 'other', 'Should we keep Pattaya CC on the schedule?', 'With the greens the way they are, is the TRGG keeping Pattaya CC every Monday? Several of us are thinking of dropping 5 Oct unless the course says what they''re doing about the back nine.', 'Travellers Rest Golf Group', 'in_progress', 'normal', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-02 19:43:18+07', '2026-10-03 09:29:37+07'),
('TRGG-GUEST-0976', 'Sykes, Jim', 'en', 'caddy_booking', 'Eastern Star booking in English please', 'Our whole TRGG group struggles with Eastern Star. The caddy master doesn''t speak English, the pro shop barely does. 8 Oct we have 5 players wanting caddies and no way to ask.', 'Travellers Rest Golf Group', 'resolved', 'high', 'Booked the caddy for them by phone in Thai and confirmed back in English.', '2026-10-04 09:35:33+07', 'U2b6d976f19bca4b2f4374ae0e10ed873', 'seed_wave4_20261004', '2026-10-02 18:40:37+07', '2026-10-04 09:37:33+07'),
('TRGG-GUEST-0845', 'Pullinen, Jyrki', 'en', 'caddy_booking', 'Can''t book Eastern Star - language barrier', 'Eastern Star LINE replies only in Thai and the phone staff don''t speak English. I just want a caddy for the TRGG day on 8 Oct. Can MyCaddiPro book it for us?', 'Travellers Rest Golf Group', 'in_progress', 'normal', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-10-02 18:00:46+07', '2026-10-04 03:05:15+07'),
('MANUAL-1787279354491-zdr0rd1', 'Hirai Nobuyoshi', 'en', 'caddy_booking', 'Can''t book Burapha - language barrier', 'Burapha LINE replies only in Thai and the phone staff don''t speak English. I just want a caddy for the TRGG day on 6 Oct. Can MyCaddiPro book it for us?', 'Travellers Rest Golf Group', 'in_progress', 'normal', 'Collecting these per course for the pro shop meeting.', NULL, NULL, 'seed_wave4_20261004', '2026-09-30 21:00:14+07', '2026-10-01 00:05:09+07'),
('U8d79efa18534ad16e71e97349e5f4412', 'Willy Gourdin', 'en', 'other', 'Pattaya CC greens on 28 Sep', 'The greens at Pattaya CC on 28 Sep were shocking. Bumpy, slow, bare patches on half of them. You can''t putt on them — it''s a lottery. What is the course doing?', 'Travellers Rest Golf Group', 'open', 'high', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-09-29 22:38:14+07', '2026-09-29 22:38:14+07'),
('TRGG-GUEST-0889', 'Scadden, Kim', 'en', 'other', 'Back nine at Pattaya CC is a disgrace', '28 Sep: the back nine greens at Pattaya CC are in the worst state since I started playing here five years ago. Holes 14 to 17 were more sand than grass. Please pass this to the course.', 'Travellers Rest Golf Group', 'open', 'high', NULL, NULL, NULL, 'seed_wave4_20261004', '2026-09-29 16:06:53+07', '2026-09-29 16:06:53+07'),
('TRGG-GUEST-0091', 'Billington, Phillip', 'en', 'other', 'Pattaya CC - greens getting worse every week', '28 Sep was worse than the week before. Sanded, sandy, and brown on the edges. Ball bounces off line from three feet. The TRGG pays good money for this course every Monday.', 'Travellers Rest Golf Group', 'in_progress', 'normal', 'Collecting the greens reports to send to Pattaya CC together.', NULL, NULL, 'seed_wave4_20261004', '2026-09-28 22:19:05+07', '2026-09-28 23:50:12+07'),
('Ubf3b7121aee6641bfd82e03566de1550', 'Folan, Mick', 'en', 'caddy_booking', 'Caddy shortage at Burapha', 'Half our flight had no caddy at Burapha on 24 Sep. The caddy master said ''too many golfers today''. They knew the TRGG was coming — we''re on their sheet every month.', 'Travellers Rest Golf Group', 'resolved', 'high', 'Passed to the course with the dates. They say they''ll hold caddies for society days.', '2026-09-27 03:01:21+07', 'U2b6d976f19bca4b2f4374ae0e10ed873', 'seed_wave4_20261004', '2026-09-26 13:35:03+07', '2026-09-27 03:09:21+07'),
